def login(username, password):
    user = find_user(username)
    if not user or not verify_password(password, user.hashed_password):
        raise AuthenticationError('Invalid credentials')
    return generate_jwt_token(user.id, roles=user.roles)

def generate_jwt_token(user_id: str, secret_key: str, expires_in: int = 3600) -> str:
    """Create signed JWT token with expiration timestamp."""
    payload = {'sub': user_id, 'exp': time.time() + expires_in, 'iat': time.time()}
    return jwt.encode(payload, secret_key, algorithm='HS256')

def decode_and_verify_token(token: str, secret_key: str) -> dict:
    try:
        payload = jwt.decode(token, secret_key, algorithms=['HS256'])
        return payload
    except jwt.ExpiredSignatureError:
        raise TokenExpiredError('JWT signature has expired')
    except jwt.InvalidTokenError:
        raise InvalidTokenError('Malformed or invalid auth token')

def require_permissions(required_permission: str):
    def decorator(fn):
        def wrapper(*args, **kwargs):
            user = get_current_user()
            if required_permission not in user.permissions:
                raise PermissionDenied('Access forbidden: insufficient role permissions')
            return fn(*args, **kwargs)
        return wrapper
    return decorator

