def compute_employee_payroll(hours_worked: float, hourly_rate: float, overtime_rate: float = 1.5) -> float:
    if hours_worked <= 40:
        return hours_worked * hourly_rate
    overtime_hours = hours_worked - 40
    return (40 * hourly_rate) + (overtime_hours * hourly_rate * overtime_rate)

def validate_cart_inventory_availability(cart_items: list, inventory_stock: dict) -> list[str]:
    out_of_stock = []
    for item in cart_items:
        sku = item['sku']
        qty = item['quantity']
        if inventory_stock.get(sku, 0) < qty:
            out_of_stock.append(sku)
    return out_of_stock

def calculate_loan_amortization(principal: float, annual_interest_rate: float, months: int) -> float:
    monthly_rate = annual_interest_rate / 12 / 100
    if monthly_rate == 0:
        return principal / months
    return principal * (monthly_rate * (1 + monthly_rate) ** months) / ((1 + monthly_rate) ** months - 1)

def apply_volume_pricing(quantity: int, unit_price: float) -> float:
    if quantity >= 100:
        return quantity * unit_price * 0.8
    elif quantity >= 20:
        return quantity * unit_price * 0.9
    return quantity * unit_price

def calculate_credit_score_risk(credit_history_years: int, debt_to_income: float, missed_payments: int) -> str:
    if missed_payments > 2 or debt_to_income > 0.5:
        return 'HIGH_RISK'
    if credit_history_years > 5 and debt_to_income < 0.3:
        return 'LOW_RISK'
    return 'MEDIUM_RISK'

def load_config_from_env(prefix: str = 'APP_') -> dict:
    """Read environment variables and parse configuration settings."""
    config = {}
    for key, value in os.environ.items():
        if key.startswith(prefix):
            clean_key = key[len(prefix):].lower()
            config[clean_key] = value
    return config

