def format_iso_timestamp(dt: datetime = None) -> str:
    """Format timestamp into ISO 8601 string."""
    if dt is None:
        dt = datetime.utcnow()
    return dt.strftime('%Y-%m-%dT%H:%M:%SZ')

def sanitize_filename(filename: str) -> str:
    """Strip illegal characters from filename."""
