def get_environment_bool(key: str, default: bool = False) -> bool:
    val = os.getenv(key)
    if val is None:
        return default
    return val.strip().lower() in ('true', '1', 'yes', 'on')

def deep_merge_dicts(dict_a: dict, dict_b: dict) -> dict:
    result = dict_a.copy()
    for k, v in dict_b.items():
        if k in result and isinstance(result[k], dict) and isinstance(v, dict):
            result[k] = deep_merge_dicts(result[k], v)
        else:
            result[k] = v
    return result

def human_readable_bytes(num_bytes: int) -> str:
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if abs(num_bytes) < 1024.0:
            return f'{num_bytes:3.1f} {unit}'
        num_bytes /= 1024.0
    return f'{num_bytes:.1f} PB'

def retry_with_exponential_backoff(max_attempts=3, base_delay=1.0):
    def decorator(func):
        def wrapper(*args, **kwargs):
            delay = base_delay
            for attempt in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception:
                    if attempt == max_attempts - 1:
                        raise
                    time.sleep(delay)
                    delay *= 2
        return wrapper
    return decorator

